p=Path('background-effects.test.js');s=p.read_text(encoding='utf-8').replace('steam originates at the pipe and rises while fire stays inside its emitter bounds','steam stays anchored to its pipe with grid-aligned drawing');s+='''\ntest('water ripples stay below each skyline instead of crossing buildings',()=>{for(const [round,shore] of [[4,212],[6,253],[8,247]]){const e=backgroundEmitters[round].find(e=>e.kind==='water');assert.ok(e.y-e.height>=shore);assert.ok(e.y<=(round===4?405:360));}});\ntest('fire and steam sprite source frames change without shifting the physical emitter',()=>{const calls=[],ctx={save(){},restore(){},drawImage(...args){calls.push(args);},fillRect(){}};const atlas={complete:true,naturalWidth:512,naturalHeight:256};const layout=depthLayout(6,{x:0,y:0},{width:720,height:395});drawBackgroundEffects(ctx,6,'near',0,layout,atlas);const a=calls[0];calls.length=0;drawBackgroundEffects(ctx,6,'near',.25,layout,atlas);const b=calls[0];assert.notEqual(a[1],b[1]);assert.deepEqual(a.slice(5),b.slice(5));assert.equal(ctx.filter,'none');});\n''';p.write_text(s,encoding='utf-8')
